import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";

const eslintConfig = defineConfig([
  ...nextVitals,
  ...nextTs,
  // Override default ignores of eslint-config-next.
  globalIgnores([
    // Default ignores of eslint-config-next:
    ".next/**",
    "out/**",
    "build/**",
    "next-env.d.ts",
    // Generated by `npm run test:coverage`: linting a coverage report is noise,
    // and its vendored scripts trip rules they were never written against.
    "coverage/**",
    // Written by the Prisma 8 CLI (contract emit, migration plan): generated,
    // content-addressed, and never edited by hand.
    "migrations/snapshots/**",
    // Prisma 8 contract artifacts (`prisma contract emit`) and the `prisma
    // skills sync` reference copies: generated files and vendor docs are not
    // ours to lint.
    "generated/**",
    ".agents/skills/**",
    ".claude/skills/**",
    ".cursor/skills/**",
    ".devin/skills/**",
  ]),
  // Prisma 8 only. Nothing may bring Prisma 7 back, and new code talks to the
  // Prisma 8 client directly: `@/lib/prisma` is a frozen compatibility layer
  // for the kit code that already used it (AGENTS.md, .agents/rules/database.md).
  {
    rules: {
      "no-restricted-imports": [
        "error",
        {
          paths: [
            { name: "@prisma/client", message: "Prisma 7 is gone. Use db8 from @/lib/db8 (Prisma ORM 8)." },
            { name: "@prisma/adapter-pg", message: "Prisma 7 is gone. Use db8 from @/lib/db8 (Prisma ORM 8)." },
          ],
          patterns: [{ group: ["@prisma/prisma7", "@prisma/prisma7/*"], message: "Prisma 7 is gone." }],
        },
      ],
    },
  },
  {
    files: ["src/platform/**", "src/modules/**", "src/themes/**", "src/verticals/**", "tests/**"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          paths: [
            { name: "@prisma/client", message: "Prisma 7 is gone. Use db8 from @/lib/db8 (Prisma ORM 8)." },
            { name: "@prisma/adapter-pg", message: "Prisma 7 is gone. Use db8 from @/lib/db8 (Prisma ORM 8)." },
            {
              name: "@/lib/prisma",
              message: "New code uses the Prisma 8 client: import { db8 } from \"@/lib/db8\" (tenantDb(ctx) in modules from phase 1).",
            },
          ],
          patterns: [{ group: ["@prisma/prisma7", "@prisma/prisma7/*"], message: "Prisma 7 is gone." }],
        },
      ],
    },
  },
]);

export default eslintConfig;
